<script lang="ts">
  import {untrack} from 'svelte';
  import {invoke} from '@tauri-apps/api/core';
  import type {Json,ValveGraphEdit,ValveGraphHost,ValveGraphNode,ValveGraphPort,WorkspaceDocument,WorkspaceSnapshot} from '../types';
  import {BLOCK_HEIGHT,BLOCK_WIDTH,CHANNEL_HEIGHT,CHANNEL_WIDTH,PALETTE,READ_ONLY_KINDS,READ_ONLY_PORT_KINDS,autoLayout,channelNodeId,compileDraft,draftError,endpointNodeId,hasDetailedCard,intersectsRect,layoutStorageKey,mergePositions,newDraft,nodeCardHeight,nodeCardLines,nodeIsActive,nodeOutputLine,nodeOutputOffset,OUTPUT_ROW_Y,portOffsetY,portsCompatible,translatePositions,visibleIds,type BlockDraft,type GraphPoint,type GraphPositions} from '../behavior-graph';

  let {workspace,onWorkspace,onUnlock,onNavigate}:{workspace:WorkspaceSnapshot;onWorkspace:(next:WorkspaceSnapshot)=>void;onUnlock:(archiveId:string)=>void;onNavigate:(node:ValveGraphNode)=>void}=$props();
  let selectedId=$state('');let selectedIds=$state<string[]>([]);let draft=$state<BlockDraft|null>(null);let draftPoint=$state<GraphPoint>({x:520,y:220});let positions=$state<GraphPositions>({});let activeLayoutKey=$state('');
  let search=$state('');let paletteSearch=$state('');let allLoaded=$state(false);let isolate=$state(false);let layers=$state<string[]>([]);let message=$state('');let busy=$state(false);
  let viewX=$state(0);let viewY=$state(0);let viewWidth=$state(1500);let viewHeight=$state(850);let panPointer=$state<number|null>(null);let panX=$state(0);let panY=$state(0);let dragNode=$state('');let dragStart=$state<GraphPoint>({x:0,y:0});let dragOrigins=$state<GraphPositions>({});
  let marqueePointer=$state<number|null>(null);let marqueeStart=$state<GraphPoint>({x:0,y:0});let marqueeCurrent=$state<GraphPoint>({x:0,y:0});let marqueeBase=$state<string[]>([]);
  let wirePort=$state('');let wirePoint=$state<GraphPoint>({x:0,y:0});let nativeText=$state('');let renameText=$state('');let occurrenceIds=$state<string[]>([]);let portChannels=$state<Record<string,string>>({});
  let laidOutGraph=$state<WorkspaceSnapshot['valveGraph']|null>(null);
  type RootSnapshot={documents:WorkspaceDocument[]};let undoStack=$state<RootSnapshot[]>([]);let redoStack=$state<RootSnapshot[]>([]);

  const graph=()=>workspace.valveGraph;
  const selectedNode=()=>graph().nodes.find(node=>node.id===selectedId);
  const selectedChannel=()=>graph().channels.find(channel=>channelNodeId(channel.name)===selectedId);
  let layerNameList=$derived.by(()=>[...new Set(graph().nodes.map(node=>node.layer))]);
  let activeLayerSet=$derived.by(()=>new Set(layers));
  let visibleIdSet=$derived.by(()=>visibleIds(graph(),{allLoaded,search,layers:activeLayerSet,isolate:isolate&&selectedId?selectedId:undefined}));
  let visibleNodeList=$derived.by(()=>graph().nodes.filter(node=>visibleIdSet.has(node.id)));
  let visibleChannelList=$derived.by(()=>graph().channels.filter(channel=>visibleIdSet.has(channelNodeId(channel.name))));
  let visibleEdgeList=$derived.by(()=>graph().edges.filter(edge=>visibleIdSet.has(endpointNodeId(graph(),edge.from))&&visibleIdSet.has(endpointNodeId(graph(),edge.to))));
  const layerNames=()=>layerNameList;
  const visible=()=>visibleIdSet;
  const visibleNodes=()=>visibleNodeList;
  const visibleChannels=()=>visibleChannelList;
  const visibleEdges=()=>visibleEdgeList;
  const palette=()=>PALETTE.filter(item=>`${item.label} ${item.description}`.toLowerCase().includes(paletteSearch.toLowerCase()));
  const draftPalette=()=>draft?PALETTE.find(item=>item.kind===draft!.kind):undefined;
  const draftHosts=()=>draftPalette()?graph().hosts.filter(host=>host.kind===draftPalette()!.hostKind):[];
  const selectedHost=()=>draft?graph().hosts.find(host=>host.id===draft!.hostId):undefined;

  $effect(()=>{const key=layoutStorageKey(workspace.rootPath,workspace.selectedMission);if(key!==activeLayoutKey){activeLayoutKey=key;let saved:GraphPositions|undefined;try{saved=JSON.parse(localStorage.getItem(key)??'null')??undefined}catch{saved=undefined}positions=mergePositions(graph(),saved);selectedId='';selectedIds=[];draft=null;undoStack=[];redoStack=[];fitView(false)}});
  $effect(()=>{const current=graph();if(current===laidOutGraph)return;laidOutGraph=current;const existing=untrack(()=>positions),next=mergePositions(current,existing);const changed=Object.keys(next).length!==Object.keys(existing).length||Object.entries(next).some(([id,point])=>existing[id]?.x!==point.x||existing[id]?.y!==point.y);if(changed)positions=next});

  function persistPositions(){localStorage.setItem(activeLayoutKey,JSON.stringify(positions))}
  function cloneRoots():RootSnapshot{return{documents:structuredClone(workspace.documents)}}
  async function refreshSnapshot(snapshot:WorkspaceSnapshot){return workspace.sessionId===0?snapshot:invoke<WorkspaceSnapshot>('refresh_workspace',{snapshot})}
  async function applyEdits(edits:ValveGraphEdit[]){if(!edits.length)return;busy=true;message='';const before=cloneRoots();try{const next=await invoke<WorkspaceSnapshot>('apply_valve_graph_edits',{snapshot:workspace,edits});undoStack=[...undoStack.slice(-49),before];redoStack=[];onWorkspace(next);message='Graph edit applied atomically.'}catch(error){message=String(error)}finally{busy=false}}
  async function restore(target:RootSnapshot,toUndo:boolean){busy=true;try{const current=cloneRoots();const next=await refreshSnapshot({...workspace,documents:structuredClone(target.documents)});if(toUndo)redoStack=[current,...redoStack].slice(0,50);else undoStack=[...undoStack.slice(-49),current];onWorkspace(next);message=toUndo?'Undo complete.':'Redo complete.'}catch(error){message=String(error)}finally{busy=false}}
  async function undo(){const target=undoStack.at(-1);if(!target)return;undoStack=undoStack.slice(0,-1);await restore(target,true)}
  async function redo(){const target=redoStack[0];if(!target)return;redoStack=redoStack.slice(1);await restore(target,false)}

  function graphPoint(event:PointerEvent|DragEvent|WheelEvent,element:SVGSVGElement|HTMLElement){const rect=element.getBoundingClientRect();return{x:viewX+(event.clientX-rect.left)*viewWidth/rect.width,y:viewY+(event.clientY-rect.top)*viewHeight/rect.height}}
  function zoomAt(factor:number,x=viewX+viewWidth/2,y=viewY+viewHeight/2){const width=Math.min(6000,Math.max(420,viewWidth*factor)),height=width*(viewHeight/viewWidth);const rx=(x-viewX)/viewWidth,ry=(y-viewY)/viewHeight;viewX=x-rx*width;viewY=y-ry*height;viewWidth=width;viewHeight=height}
  function wheel(event:WheelEvent){event.preventDefault();const point=graphPoint(event,event.currentTarget as SVGSVGElement);zoomAt(event.deltaY<0?.82:1.22,point.x,point.y)}
  function fitView(pad=true){const ids=visible();const points=Object.entries(positions).filter(([id])=>ids.has(id)).map(([id,point])=>({point,size:nodeSize(id)}));if(!points.length){viewX=0;viewY=0;viewWidth=1500;viewHeight=850;return}const minX=Math.min(...points.map(item=>item.point.x)),minY=Math.min(...points.map(item=>item.point.y)),maxX=Math.max(...points.map(item=>item.point.x+item.size.w)),maxY=Math.max(...points.map(item=>item.point.y+item.size.h));const padding=pad?100:50;viewX=minX-padding;viewY=minY-padding;viewWidth=Math.max(700,maxX-minX+padding*2);viewHeight=Math.max(430,maxY-minY+padding*2)}
  function marqueeRect(){return{x:Math.min(marqueeStart.x,marqueeCurrent.x),y:Math.min(marqueeStart.y,marqueeCurrent.y),w:Math.abs(marqueeCurrent.x-marqueeStart.x),h:Math.abs(marqueeCurrent.y-marqueeStart.y)}}
  function marqueeHits(){const rect=marqueeRect(),ids=[...visibleNodes().map(node=>node.id),...visibleChannels().map(channel=>channelNodeId(channel.name))];return ids.filter(id=>intersectsRect(positions[id]??{x:0,y:0},nodeSize(id),rect))}
  function canvasDown(event:PointerEvent){const svg=event.currentTarget as SVGSVGElement;if(event.button===0||event.button===1){panPointer=event.pointerId;panX=event.clientX;panY=event.clientY;svg.setPointerCapture(event.pointerId);return}if(event.button!==2)return;event.preventDefault();const point=graphPoint(event,svg);marqueePointer=event.pointerId;marqueeStart=point;marqueeCurrent=point;marqueeBase=event.shiftKey?[...selectedIds]:[];if(!event.shiftKey)selectedIds=[];draft=null;svg.setPointerCapture(event.pointerId)}
  function nodeDown(event:PointerEvent,id:string){event.stopPropagation();if(event.button!==0)return;const svg=(event.currentTarget as SVGGElement).ownerSVGElement!;const point=graphPoint(event,svg),moving=selectedIds.includes(id)?selectedIds:[id];selectedIds=[...moving];selectedId=id;dragNode=id;dragStart=point;dragOrigins=Object.fromEntries(moving.map(item=>[item,{...(positions[item]??{x:0,y:0})}]));draft=null;(event.currentTarget as SVGGElement).setPointerCapture(event.pointerId)}
  function move(event:PointerEvent){const svg=event.currentTarget as SVGSVGElement;const point=graphPoint(event,svg);wirePoint=point;if(dragNode){positions=translatePositions(positions,dragOrigins,point.x-dragStart.x,point.y-dragStart.y);return}if(marqueePointer===event.pointerId){marqueeCurrent=point;return}if(panPointer===event.pointerId){const rect=svg.getBoundingClientRect();viewX-=(event.clientX-panX)*viewWidth/rect.width;viewY-=(event.clientY-panY)*viewHeight/rect.height;panX=event.clientX;panY=event.clientY}}
  function up(event:PointerEvent){if(panPointer===event.pointerId)panPointer=null;if(marqueePointer===event.pointerId){selectedIds=[...new Set([...marqueeBase,...marqueeHits()])];marqueePointer=null;const next=selectedIds.includes(selectedId)?selectedId:selectedIds[0]??'';if(next.startsWith('channel::'))selectChannel(next.slice('channel::'.length));else{const node=graph().nodes.find(item=>item.id===next);if(node)selectNode(node);else selectedId=''}}if(dragNode){dragNode='';persistPositions()}wirePort=''}
  function nodeSize(id:string){if(id.startsWith('channel::'))return{w:CHANNEL_WIDTH,h:CHANNEL_HEIGHT};const node=graph().nodes.find(item=>item.id===id);return{w:BLOCK_WIDTH,h:node?nodeCardHeight(node):BLOCK_HEIGHT}}
  function portPoint(portId:string){for(const node of graph().nodes){const index=node.ports.findIndex(port=>port.id===portId);if(index>=0){const point=positions[node.id]??{x:0,y:0};const port=node.ports[index];return{x:point.x+(port.direction==='write'?BLOCK_WIDTH:0),y:point.y+portOffsetY(node,index)}}}return positions[endpointNodeId(graph(),portId)]??{x:0,y:0}}
  function endpointPoint(id:string,isFrom:boolean){if(id.startsWith('channel::')){const point=positions[id]??{x:0,y:0};return{x:point.x+(isFrom?CHANNEL_WIDTH:0),y:point.y+CHANNEL_HEIGHT/2}}
    // Route edges attach to whole cards: out of the right edge, into the left edge at the label row.
    if(graph().nodes.some(node=>node.id===id)){const point=positions[id]??{x:0,y:0};return{x:point.x+(isFrom?BLOCK_WIDTH:0),y:point.y+40}}
    return portPoint(id)}
  function edgePath(from:string,to:string){const a=endpointPoint(from,true),b=endpointPoint(to,false),curve=Math.max(60,Math.abs(b.x-a.x)*.45);return`M ${a.x} ${a.y} C ${a.x+curve} ${a.y}, ${b.x-curve} ${b.y}, ${b.x} ${b.y}`}
  function portById(id:string){return graph().nodes.flatMap(node=>node.ports).find(port=>port.id===id)}
  function beginWire(event:PointerEvent,port:ValveGraphPort){event.stopPropagation();wirePort=port.id;wirePoint=portPoint(port.id)}
  async function connectPort(port:ValveGraphPort,channel:string){if(!channel.trim())return;if(wouldCreateCycle(port,channel)&&!window.confirm(`Connecting ${channel} here creates a derived-state cycle. Create it anyway?`))return;await applyEdits([{operation:'connect',portId:port.id,channelName:channel.trim()}])}
  function wouldCreateCycle(port:ValveGraphPort,channel:string){const owner=graph().nodes.find(node=>node.ports.some(item=>item.id===port.id));if(!owner)return false;const links=new Map<string,string[]>();for(const node of graph().nodes){const reads=node.ports.filter(item=>item.direction==='read').map(item=>item.id===port.id?channel:item.channel),writes=node.ports.filter(item=>item.direction==='write').map(item=>item.id===port.id?channel:item.channel);for(const read of reads)links.set(read,[...(links.get(read)??[]),...writes])}const visit=(name:string,target:string,seen:Set<string>):boolean=>name===target||!seen.has(name)&&((seen.add(name)),(links.get(name)??[]).some(next=>visit(next,target,seen)));return owner.ports.some(item=>item.direction==='write'&&visit(item.channel,channel,new Set()))}
  async function dropOnPort(event:PointerEvent,target:ValveGraphPort){event.stopPropagation();if(!wirePort||wirePort===target.id){wirePort='';return}const source=portById(wirePort);wirePort='';if(!source||!portsCompatible(source,target)){message='Ports must have opposite read/write directions.';return}const output=source.direction==='write'?source:target,input=source.direction==='read'?source:target;await connectPort(input,output.channel)}
  async function dropOnChannel(_event:PointerEvent,name:string){const source=portById(wirePort);wirePort='';if(source)await connectPort(source,name)}
  function selectNode(node:ValveGraphNode){selectedId=node.id;if(!selectedIds.includes(node.id))selectedIds=[node.id];draft=null;nativeText=JSON.stringify(node.nativeRecord,null,2);portChannels=Object.fromEntries(node.ports.map(port=>[port.id,port.channel]))}
  function selectChannel(name:string){selectedId=channelNodeId(name);if(!selectedIds.includes(selectedId))selectedIds=[selectedId];draft=null;renameText=name;occurrenceIds=graph().nodes.filter(node=>!READ_ONLY_PORT_KINDS.has(node.kind)).flatMap(node=>node.ports).filter(port=>port.channel===name).map(port=>port.id)}
  function startDraft(kind:string,point?:GraphPoint){draft=newDraft(kind);const host=draftHosts().find(item=>!item.locked);if(host)draft.hostId=host.id;draftPoint=point??{x:viewX+viewWidth/2-BLOCK_WIDTH/2,y:viewY+viewHeight/2-BLOCK_HEIGHT/2};selectedId='';selectedIds=[]}
  function paletteDrag(event:DragEvent,kind:string){event.dataTransfer?.setData('application/x-mech-valve-block',kind);if(event.dataTransfer)event.dataTransfer.effectAllowed='copy'}
  function canvasDrop(event:DragEvent){event.preventDefault();const kind=event.dataTransfer?.getData('application/x-mech-valve-block');if(kind)startDraft(kind,graphPoint(event,event.currentTarget as HTMLElement))}
  async function applyDraft(){if(!draft)return;const host=selectedHost(),error=draftError(draft,host);if(error){message=error;return}const record=compileDraft(draft,host!);await applyEdits([{operation:'addBlock',blockKind:draft.kind,hostId:host!.id,nativeRecord:record}]);draft=null}
  async function updateNative(){const node=selectedNode();if(!node)return;try{await applyEdits([{operation:'updateBlock',nodeId:node.id,nativeRecord:JSON.parse(nativeText) as Json}])}catch(error){message=String(error)}}
  async function removeNode(){const node=selectedNode();if(!node||!window.confirm(`Remove ${node.label} from ${node.binding.entryName}?`))return;await applyEdits([{operation:'removeBlock',nodeId:node.id}]);selectedId='';selectedIds=selectedIds.filter(id=>id!==node.id)}
  async function renameChannel(){const channel=selectedChannel();if(!channel||!renameText.trim())return;if(!window.confirm(`Rename ${occurrenceIds.length} selected recognized occurrence(s) from ${channel.name} to ${renameText.trim()}? Scripts and unloaded Readers cannot be rewritten.`))return;const oldId=selectedId;await applyEdits([{operation:'renameChannel',oldName:channel.name,newName:renameText.trim(),occurrenceIds}]);selectedId=channelNodeId(renameText.trim());selectedIds=selectedIds.map(id=>id===oldId?selectedId:id)}
  function archiveId(documentId:string){const document=workspace.documents.find(item=>item.id===documentId);return document?.archiveId??''}
  function toggleLayer(layer:string){layers=layers.includes(layer)?layers.filter(item=>item!==layer):[...layers,layer]}
  function toggleOccurrence(id:string){occurrenceIds=occurrenceIds.includes(id)?occurrenceIds.filter(item=>item!==id):[...occurrenceIds,id]}
</script>

<div class="behavior-shell">
  <aside class="behavior-palette">
    <div class="side-heading"><div><small>BEHAVIOR GRAPH</small><b>Block palette</b></div></div>
    <input class="graph-search" placeholder="Search blocks…" bind:value={paletteSearch}>
    {#each ['producer','logic','consumer'] as category}<div class="section-label">{category}</div>{#each palette().filter(item=>item.category===category) as item}<button class="palette-block" draggable="true" ondragstart={event=>paletteDrag(event,item.kind)} onclick={()=>startDraft(item.kind)}><b>{item.label}</b><small>{item.description}</small></button>{/each}{/each}
    <p class="palette-help">Drag a block onto the canvas or click it. Drafts stay local until a writable native host is selected and Apply is pressed.</p>
  </aside>

  <section class="behavior-workspace">
    <div class="behavior-toolbar">
      <div><small>{graph().scopeKey.toUpperCase()||'MISSION'}</small><h2>Behavior Graph</h2></div>
      <div class="graph-tools"><input placeholder="Search channels and blocks…" bind:value={search}><label><input type="checkbox" bind:checked={allLoaded}> All loaded channels</label><button class:active={isolate} disabled={!selectedId} onclick={()=>isolate=!isolate}>Isolate chain</button><button disabled={!undoStack.length||busy} onclick={undo}>Undo</button><button disabled={!redoStack.length||busy} onclick={redo}>Redo</button><div class="zoom-controls"><button title="Zoom out" onclick={()=>zoomAt(1.22)}>−</button><span>{Math.round(1500/viewWidth*100)}%</span><button title="Zoom in" onclick={()=>zoomAt(.82)}>+</button><button onclick={()=>fitView()}>Fit</button><button onclick={()=>{positions=autoLayout(graph());persistPositions();fitView()}}>Auto-layout</button></div></div>
    </div>
    <div class="layer-filter"><span>Layers:</span>{#each layerNames() as layer}<button class:active={!layers.length||layers.includes(layer)} onclick={()=>toggleLayer(layer)}>{layer}</button>{/each}<span class="graph-count">{visibleNodes().length} blocks · {visibleChannels().length} channels{selectedIds.length>1?` · ${selectedIds.length} selected`:''}</span></div>
    {#if message}<div class="graph-message">{message}<button aria-label="Dismiss message" onclick={()=>message=''}>×</button></div>{/if}
    <div class="behavior-layout">
      <div class="behavior-canvas" role="presentation" ondragover={event=>event.preventDefault()} ondrop={canvasDrop}>
        <svg class:panning={panPointer!==null} class:selecting={marqueePointer!==null} viewBox={`${viewX} ${viewY} ${viewWidth} ${viewHeight}`} role="application" aria-label="Valve behavior graph. Left-drag or middle-drag empty space to pan, right-drag empty space to rectangle-select, drag selected nodes to move them together, and use the wheel to zoom." onwheel={wheel} onpointerdown={canvasDown} onpointermove={move} onpointerup={up} onpointercancel={up} oncontextmenu={event=>event.preventDefault()}>
          <defs><pattern id="behavior-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M 30 0 L 0 0 0 30" fill="none" stroke="#203138" stroke-width="1"/></pattern><marker id="behavior-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>
          <rect x={viewX-100} y={viewY-100} width={viewWidth+200} height={viewHeight+200} fill="#081115"/><rect x={viewX-100} y={viewY-100} width={viewWidth+200} height={viewHeight+200} fill="url(#behavior-grid)"/>
          {#each visibleEdges() as edge (edge.id)}<path class="behavior-edge" class:route={edge.kind==='route'} d={edgePath(edge.from,edge.to)} marker-end="url(#behavior-arrow)"><title>{edge.kind==='route'?`Network route: ${edge.channel}`:edge.channel}</title></path>{/each}
          {#if wirePort}{@const start=portPoint(wirePort)}<path class="behavior-edge draft-wire" d={`M ${start.x} ${start.y} L ${wirePoint.x} ${wirePoint.y}`}/>{/if}
          {#if marqueePointer!==null}{@const rect=marqueeRect()}<rect class="selection-marquee" x={rect.x} y={rect.y} width={rect.w} height={rect.h}/>{/if}
          {#each visibleChannels() as channel (channel.id)}{@const id=channelNodeId(channel.name)}{@const point=positions[id]??{x:0,y:0}}<g class="channel-block" class:selected={selectedIds.includes(id)} transform={`translate(${point.x} ${point.y})`} role="button" tabindex="0" aria-label={`Channel ${channel.name}`} onpointerdown={event=>nodeDown(event,id)} onpointerup={event=>dropOnChannel(event,channel.name)} onclick={()=>selectChannel(channel.name)} onkeydown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectChannel(channel.name)}}}><rect width={CHANNEL_WIDTH} height={CHANNEL_HEIGHT} rx="24"/><text class="channel-name" x={CHANNEL_WIDTH/2} y="27" text-anchor="middle">{channel.name}</text><text class="channel-count" x={CHANNEL_WIDTH/2} y="46" text-anchor="middle">{channel.producerCount} write · {channel.consumerCount} read</text></g>{/each}
          {#each visibleNodes() as node (node.id)}{@const point=positions[node.id]??{x:0,y:0}}{@const cardHeight=nodeCardHeight(node)}{@const cardLines=nodeCardLines(node)}{@const outputLine=nodeOutputLine(node)}{@const offset=nodeOutputOffset(node)}<g class="behavior-node {node.category}" class:selected={selectedIds.includes(node.id)} class:locked={node.locked} transform={`translate(${point.x} ${point.y})`} role="button" tabindex="0" aria-label={`${node.label}, ${node.kind}`} onpointerdown={event=>nodeDown(event,node.id)} onclick={()=>selectNode(node)} onkeydown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectNode(node)}}}><rect width={BLOCK_WIDTH} height={cardHeight} rx="10"/><rect class="node-stripe" width="7" height={cardHeight} rx="4"/><text class="node-kind" x="18" y="23">{node.kind.replaceAll('-',' ')}</text><text class="node-label" x="18" y="45">{node.label.slice(0,28)}</text><text class="node-subtitle" x="18" y="64">{node.subtitle.slice(0,32)}</text>{#if outputLine}<text class="node-output" x="18" y={OUTPUT_ROW_Y}>→ {outputLine.slice(0,30)}<title>Writes: {outputLine}</title></text>{/if}{#if hasDetailedCard(node)}{#if node.kind==='vlist-producer'}<circle class:active={nodeIsActive(node)} class="vlist-status" cx="202" cy="22" r="6"><title>{nodeIsActive(node)?'Active':'Inactive'}</title></circle>{/if}{#each cardLines as line,index}<text class="node-condition" x="18" y={84+offset+index*14}>{line.slice(0,34)}<title>{line}</title></text>{/each}<text class="node-layer" x="18" y={cardHeight-10}>{node.layer}{node.locked?' · locked':''}</text>{:else}<text class="node-layer" x="18" y={88+offset}>{node.layer}{node.locked?' · locked':''}</text>{/if}{#each node.ports as port,index (port.id)}{@const px=port.direction==='write'?BLOCK_WIDTH:0}{@const py=portOffsetY(node,index)}<circle class="graph-port {port.direction}" cx={px} cy={py} r="7" role="button" tabindex="0" aria-label={`${port.direction} ${port.channel}`} onpointerdown={event=>beginWire(event,port)} onpointerup={event=>dropOnPort(event,port)} onkeydown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectNode(node)}}}><title>{port.label}: {port.channel} {port.value===undefined?'':`= ${port.value}`}</title></circle>{/each}</g>{/each}
          {#if draft}{@const item=draftPalette()}<g class="behavior-node draft" transform={`translate(${draftPoint.x} ${draftPoint.y})`}><rect width={BLOCK_WIDTH} height={BLOCK_HEIGHT} rx="10"/><rect class="node-stripe" width="7" height={BLOCK_HEIGHT} rx="4"/><text class="node-kind" x="18" y="23">UNAPPLIED DRAFT</text><text class="node-label" x="18" y="48">{item?.label}</text><text class="node-subtitle" x="18" y="72">Configure in the inspector</text></g>{/if}
        </svg>
        <div class="behavior-minimap" aria-hidden="true"><svg viewBox="0 0 1500 850">{#each visibleEdges() as edge}<path d={edgePath(edge.from,edge.to)}/>{/each}{#each [...visibleNodes().map(node=>node.id),...visibleChannels().map(channel=>channelNodeId(channel.name))] as id}{@const p=positions[id]??{x:0,y:0}}{@const size=nodeSize(id)}<rect x={p.x} y={p.y} width={size.w} height={size.h}/>{/each}<rect class="mini-view" x={viewX} y={viewY} width={viewWidth} height={viewHeight}/></svg></div>
        <div class="graph-legend"><span class="producer">Producer</span><span class="channel">Channel</span><span class="logic">Logic / delay</span><span class="consumer">Consumer</span><span class="unknown">Unknown / raw</span><em>Left/middle-drag: pan · Right-drag: select · Shift-right-drag: add</em></div>
      </div>

      <aside class="graph-inspector">
        {#if draft}{@const host=selectedHost()}<div class="property-title"><div><small>UNAPPLIED DRAFT</small><h3>{draftPalette()?.label}</h3></div><button onclick={()=>draft=null}>Cancel</button></div><p>{draftPalette()?.description}</p>
          <label><span>Writable native host</span><select bind:value={draft.hostId}><option value="">Select existing document…</option>{#each draftHosts() as item}<option value={item.id} disabled={item.locked}>{item.label} · {item.layer}{item.locked?' (locked)':''}</option>{/each}</select></label>
          {#if host?.locked}<div class="locked-card"><p>{host.archiveRelativePath} is locked.</p><button onclick={()=>onUnlock(archiveId(host.documentId))}>Unlock archive</button></div>{/if}
          {#if !draftHosts().length}<p class="field-error">The required ZRD or native container is absent. The draft will not create an archive entry.</p>{/if}
          {#if draft.kind!=='net-valveunion'}<label><span>{draft.kind==='valve-delayupdate'?'Trigger channel':'Channel name'}</span><input bind:value={draft.channel} placeholder="exact_case_sensitive_name"></label>{/if}
          {#if ['derived-any-nonzero','derived-all-nonzero','derived-all-zero','net-valveunion'].includes(draft.kind)}<label><span>Input channels (comma separated)</span><textarea bind:value={draft.members}></textarea></label>{/if}
          {#if draft.kind==='valve-delayupdate'}<label><span>Output channel</span><input bind:value={draft.targetChannel}></label><label><span>Delay</span><input type="number" step="any" bind:value={draft.delay}></label>{/if}
          {#if draft.kind==='vlist-producer'}<label><span>Existing region</span><input bind:value={draft.region} list="region-names"></label><div class="inline-checks"><label><input type="checkbox" bind:checked={draft.enters}> Enters</label><label><input type="checkbox" bind:checked={draft.exits}> Exits</label></div>{/if}
          {#if draft.kind==='target-health-producer'}<label><span>Health threshold</span><input type="number" step="any" bind:value={draft.threshold}></label>{/if}
          {#if ['valve-sound','valve-sound_once'].includes(draft.kind)}<label><span>Sound name</span><input bind:value={draft.name}></label>{/if}
          {#if ['valve-shutdown','valve-destroy','valve-teleport','valve-attack_strategy'].includes(draft.kind)}<label><span>Existing vehicle</span><input bind:value={draft.name} list="vehicle-names"></label>{/if}
          {#if draft.kind==='valve-teleport'}<div class="coordinate-grid">{#each ['x','y','z','yaw'] as key}<label><span>{key.toUpperCase()}</span><input type="number" step="any" bind:value={draft[key as 'x'|'y'|'z'|'yaw']}></label>{/each}</div>{/if}
          {#if draft.kind==='valve-attack_strategy'}<label><span>Strategy / parameter</span><input type="number" step="any" bind:value={draft.threshold}></label>{/if}
          {#if draft.kind==='objective-observer'}<label><span>Description resource key</span><input bind:value={draft.description}></label><label><span>Navigation marker</span><input bind:value={draft.nav}></label>{/if}
          {#if !['derived-any-nonzero','derived-all-nonzero','derived-all-zero','valve-delayupdate'].includes(draft.kind)}<label><span>Integer state value</span><input type="number" step="1" bind:value={draft.value}></label>{/if}
          <datalist id="region-names">{#each workspace.references.filter(item=>item.role==='defines-region') as item}<option value={item.name}></option>{/each}</datalist><datalist id="vehicle-names">{#each workspace.references.filter(item=>item.role==='defines-vehicle') as item}<option value={item.name}></option>{/each}</datalist>
          {#if draftError(draft,host)}<p class="draft-requirement">{draftError(draft,host)}</p>{/if}<button class="primary wide" disabled={!!draftError(draft,host)||busy} onclick={applyDraft}>Apply to native record</button>
        {:else if selectedNode()}{@const node=selectedNode()!}<div class="property-title"><div><small>{node.kind.toUpperCase()}</small><h3>{node.label}</h3></div>{#if !READ_ONLY_KINDS.has(node.kind)}<button class="danger" disabled={node.locked} onclick={removeNode}>Delete</button>{/if}</div><p>{node.subtitle}</p>{#if node.kind==='animation-callback'}<ul class="animation-facts">{#each nodeCardLines(node) as line}<li>{line}</li>{/each}</ul><p class="warning-text">Callbacks 42/43 set the definition NAME channel to 0/1 (executable trace). The channel is the animation's identity, so it cannot be rebound here.</p>{/if}<dl class="binding-data"><dt>Source</dt><dd>{node.binding.archiveRelativePath} / {node.binding.entryName}</dd><dt>Native locator</dt><dd>{node.binding.locator}</dd><dt>Layer</dt><dd>{node.layer}</dd></dl>
          {#if node.locked}<div class="locked-card"><p>This native record is inspectable but immutable.</p><button onclick={()=>onUnlock(archiveId(node.binding.documentId))}>Unlock archive</button></div>{/if}
          <div class="property-section"><h4>Typed channel ports</h4>{#each node.ports as port}<label><span>{port.label} · {port.direction}{port.value===undefined?'':` · value ${port.value}`}</span><div class="connection-row"><input list="channel-names" value={portChannels[port.id]??port.channel} oninput={event=>portChannels={...portChannels,[port.id]:event.currentTarget.value}}><button disabled={node.locked||READ_ONLY_PORT_KINDS.has(node.kind)||!(portChannels[port.id]??'').trim()} onclick={()=>connectPort(port,portChannels[port.id]??'')}>Connect</button>{#if port.binding.removeContainerPath}<button disabled={node.locked} onclick={()=>applyEdits([{operation:'disconnect',portId:port.id}])}>Remove input</button>{/if}</div></label>{/each}<datalist id="channel-names">{#each graph().channels as channel}<option value={channel.name}></option>{/each}</datalist></div>
          <div class="property-section"><h4>Native record</h4>{#if READ_ONLY_KINDS.has(node.kind)}<p>{node.kind==='unknown-action'?'Unknown records are deliberately read-only.':'Animation records are shown read-only.'}</p><pre>{nativeText}</pre>{:else}<textarea class="native-record" disabled={node.locked} bind:value={nativeText}></textarea><button disabled={node.locked||busy} onclick={updateNative}>Apply record update</button>{/if}</div><button class="wide" onclick={()=>onNavigate(node)}>Open in native editor</button>
        {:else if selectedChannel()}{@const channel=selectedChannel()!}<div class="property-title"><div><small>STATE CHANNEL</small><h3>{channel.name}</h3></div></div><p>Exact, case-sensitive integer state channel.</p><dl class="binding-data"><dt>Producers</dt><dd>{channel.producerCount}</dd><dt>Consumers</dt><dd>{channel.consumerCount}</dd><dt>Layers</dt><dd>{channel.layers.join(', ')}</dd></dl><label><span>New exact name</span><input bind:value={renameText}></label><div class="property-section"><h4>Recognized occurrences</h4>{#each graph().nodes.flatMap(node=>node.ports.map(port=>({node,port}))).filter(item=>item.port.channel===channel.name) as item}<label class="occurrence"><input type="checkbox" disabled={READ_ONLY_PORT_KINDS.has(item.node.kind)} checked={occurrenceIds.includes(item.port.id)} onchange={()=>toggleOccurrence(item.port.id)}><span><b>{item.node.label}</b><small>{item.port.label} · {item.node.binding.archiveRelativePath} / {item.node.binding.entryName}{item.node.locked?' · locked':''}</small></span></label>{/each}</div><p class="warning-text">Scripts, raw unknown records, and unloaded Readers cannot be rewritten.</p><button class="primary wide" disabled={!renameText.trim()||renameText===channel.name||!occurrenceIds.length||busy} onclick={renameChannel}>Rename selected occurrences</button>
        {:else}<div class="empty"><h3>Select a block or channel</h3><p>Drag ports to channels to rebind them. Use the inspector controls for keyboard-accessible connections.</p><p>Regions, vehicles, sounds, targets, nets, phases, layers, and source paths appear as metadata; only named state is represented as a channel.</p></div>{/if}
        {#if graph().diagnostics.length}<details class="graph-diagnostics"><summary>{graph().diagnostics.length} graph diagnostic{graph().diagnostics.length===1?'':'s'}</summary>{#each graph().diagnostics as diagnostic}<button class="diagnostic {diagnostic.severity}" onclick={()=>{if(diagnostic.nodeId){selectedId=diagnostic.nodeId;const node=selectedNode();if(node)selectNode(node)}}}><b>{diagnostic.code}</b><span>{diagnostic.message}</span></button>{/each}</details>{/if}
      </aside>
    </div>
  </section>
</div>
